import React from "react";

function BottomNav({ active }) {
    const navStyle = {
        position: "fixed",
        bottom: 0,
        width: "100%",
        display: "flex",
        justifyContent: "space-around",
        padding: "15px 0 25px 0",
        background: "white",
        borderTopLeftRadius: "30px",
        borderTopRightRadius: "30px",
        boxShadow: "0 -10px 30px rgba(0,0,0,0.05)"
    };

    const itemStyle = (isActive) => ({
        textAlign: "center",
        flex: 1,
        color: isActive ? "#a82324" : "#BDC3C7",
        textDecoration: "none",
        fontWeight: 700,
        fontSize: 10,
    });

    return (
        <div style={navStyle}>
            <a style={itemStyle(active === "home")} href="/home">Home</a>
            <a style={itemStyle(active === "cities")} href="/cities">Cities</a>
            <a style={itemStyle(active === "chat")} href="/chat">Chat</a>
            <a style={itemStyle(active === "profile")} href="/profile">Profile</a>
        </div>
    );
}

export default BottomNav;
